  ('al-1', 'power', 'warning', 'hyd', 'hyd-amp', st_point(78.445, 17.44)::geography, '{"en":"Scheduled power cut: SR Nagar, Ameerpet","te":"షెడ్యూల్డ్ కరెంట్ కోత: ఎస్‌ఆర్ నగర్, అమీర్‌పేట"}'::jsonb, '{"en":"10 AM – 1 PM for feeder maintenance","te":"ఫీడర్ నిర్వహణ కోసం ఉదయం 10 – మధ్యాహ్నం 1"}'::jsonb, '2026-11-16T05:01:46.896Z', '2026-11-16T08:01:46.896Z'),
  ('al-2', 'water', 'info', 'hyd', 'hyd-sec', st_point(78.505, 17.445)::geography, '{"en":"No water supply in Marredpally tomorrow","te":"రేపు మారేడ్‌పల్లిలో నీటి సరఫరా ఉండదు"}'::jsonb, '{"en":"Pipeline repair; tankers on request via 155313","te":"పైప్‌లైన్ మరమ్మతు; 155313కు కాల్ చేస్తే ట్యాంకర్"}'::jsonb, '2026-11-16T23:01:46.896Z', null),
